// ShowSubcommandHelp prints help for the given subcommand
func ShowSubcommandHelp(cCtx *Context) error {
	if cCtx == nil {
		return nil
	}

	if cCtx.Command != nil {
		return ShowCommandHelp(cCtx, cCtx.Command.Name)
	}

	return ShowCommandHelp(cCtx, "")
}

